interface Product {
  id: number;
  name: string;
  price: number;
  readonly sku: string;
}

const notebook: Product = { id: 2, name: "Notebook", sku: "NB-01" };

const stapler: Product = { id: 3, name: "Stapler", price: 8, sku: "ST-01", color: "red" };

interface Named {
  name: string;
}

function hello(entity: Named): string {
  return `Hello, ${entity.name}!`;
}

const city = { name: "Lisbon", population: 545000 };
const robot = { model: "RX-78" };

console.log(hello(city));
console.log(hello(robot));

interface Entity {
  id: number;
  createdAt: string;
}

interface Customer extends Entity {
  email: string;
  greet(): string;
}

const customer: Customer = {
  id: 7,
  createdAt: "2026-03-01",
  email: "ada@example.com",
  greet() {
    return `Customer #${this.id} <${this.email}>`;
  },
};

interface Scores {
  [player: string]: number;
}

const scores: Scores = { ada: 10 };
scores["grace"] = 12;

console.log(customer.greet());
console.log(scores);
